def transform(grid):
    h, w = len(grid), len(grid[0])

    sep_rows = [r for r in range(h) if all(v == 8 for v in grid[r])]
    sep_cols = [c for c in range(w) if all(grid[r][c] == 8 for r in range(h))]

    def bands(n, separators):
        result = []
        start = 0
        for s in separators:
            if start < s:
                result.append((start, s))
            start = s + 1
        if start < n:
            result.append((start, n))
        return result

    rb = bands(h, sep_rows)
    cb = bands(w, sep_cols)
    nr, nc = len(rb), len(cb)

    seeds = {2: set(), 3: set()}
    for i, (r0, r1) in enumerate(rb):
        for j, (c0, c1) in enumerate(cb):
            for color in seeds:
                if any(grid[r][c] == color
                       for r in range(r0, r1)
                       for c in range(c0, c1)):
                    seeds[color].add((i, j))

    painted = {2: set(), 3: set()}
    for color, points in seeds.items():
        for i in range(nr):
            js = [j for r, j in points if r == i]
            if len(js) >= 2:
                painted[color].update((i, j) for j in range(min(js), max(js) + 1))
        for j in range(nc):
            is_ = [i for i, c in points if c == j]
            if len(is_) >= 2:
                painted[color].update((i, j) for i in range(min(is_), max(is_) + 1))

    out = [row[:] for row in grid]
    for i, (r0, r1) in enumerate(rb):
        for j, (c0, c1) in enumerate(cb):
            has2 = (i, j) in painted[2] or (i, j) in seeds[2]
            has3 = (i, j) in painted[3] or (i, j) in seeds[3]
            color = 6 if has2 and has3 else (2 if has2 else (3 if has3 else None))
            if color is not None:
                for r in range(r0, r1):
                    for c in range(c0, c1):
                        out[r][c] = color
    return out
